INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine höhere Bit-Tiefe immer die Dateigröße verdoppelt?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Bit-Schritten ab"}, {"text": "Ja", "correct": false, "because": "Nicht immer Verdopplung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bestimmt die Genauigkeit eines digitalen Signals?', 3, '[{"text": "Bit-Tiefe", "correct": true, "because": "Misst Amplitudenauflösung"}, {"text": "Abtastrate", "correct": false, "because": "Misst Zeitauflösung"}, {"text": "Dateikompression", "correct": false, "because": "Beeinflusst Speicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Qualität einer Audiodigitalisierung?', 5, '[{"text": "Bit-Tiefe", "correct": true, "because": "Bestimmt Dynamikbereich"}, {"text": "Abtastrate", "correct": true, "because": "Bestimmt Frequenzbereich"}, {"text": "Dateiname", "correct": false, "because": "Kein Qualitätsfaktor"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 16 Bit bieten mehr Dynamik als 8 Bit. b) Sie verdoppeln immer die Dateigröße.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Größe nicht immer doppelt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl einer Bit-Tiefe für Audio?', 4, '[{"text": "Dynamikbereich", "correct": false, "because": "Kern der Qualität"}, {"text": "Speicherbedarf", "correct": false, "because": "Beeinflusst Größe"}, {"text": "Aufnahmelautstärke", "correct": true, "because": "Kein Bit-Tiefenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Bit-Tiefe von 24 Bit besser als 16 Bit ist?', 2, '[{"text": "Ja", "correct": true, "because": "Größerer Dynamikbereich"}, {"text": "Nein", "correct": false, "because": "24 Bit präziser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bit-Tiefe ist typisch für professionelle Audioaufnahmen?', 4, '[{"text": "24 Bit", "correct": true, "because": "Hohe Präzision und Dynamik"}, {"text": "8 Bit", "correct": false, "because": "Zu geringe Qualität"}, {"text": "12 Bit", "correct": false, "because": "Selten verwendet"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine höhere Bit-Tiefe immer hörbar besseren Klang liefert. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Ohr und Equipment"}, {"text": "Ja", "correct": false, "because": "Nicht immer wahrnehmbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Beeinflusst die Bit-Tiefe die Frequenz eines Signals?', 2, '[{"text": "Nein", "correct": true, "because": "Frequenz durch Abtastrate"}, {"text": "Ja", "correct": false, "because": "Bit-Tiefe für Amplituden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte sind typisch für die Bit-Tiefe in Audioanwendungen?', 4, '[{"text": "16 Bit", "correct": true, "because": "Standard für CDs"}, {"text": "24 Bit", "correct": true, "because": "Für Studioaufnahmen"}, {"text": "64 Bit", "correct": false, "because": "Zu hoch für Audio"}, {"text": "4 Bit", "correct": false, "because": "Zu niedrig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl einer Bit-Tiefe für eine Aufnahme?', 4, '[{"text": "Dynamikbereich", "correct": true, "because": "Sichert Klangqualität"}, {"text": "Minimale Dateigröße", "correct": false, "because": "Qualität wichtiger"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bit-Tiefe misst Amplitudenauflösung. b) Sie bestimmt die maximale Frequenz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Frequenz durch Abtastrate"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Wahl einer Bit-Tiefe?', 3, '[{"text": "Dynamikbedarf", "correct": false, "because": "Bestimmt Präzision"}, {"text": "Speicherplatz", "correct": false, "because": "Beeinflusst Entscheidung"}, {"text": "Aufnahmeort", "correct": true, "because": "Kein Bit-Tiefenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Bit-Tiefe für Musikstreaming wähle?', 4, '[{"text": "16 Bit für Kompatibilität", "correct": true, "because": "Standard für Streaming"}, {"text": "8 Bit für Qualität", "correct": false, "because": "Zu niedrig"}, {"text": "32 Bit für Größe", "correct": false, "because": "Übertrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 8 Bit für moderne Audioaufnahmen ausreicht. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Zu geringe Dynamik"}, {"text": "Ja", "correct": false, "because": "16 oder 24 Bit nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkung hat eine Bit-Tiefe von 16 Bit gegenüber 8 Bit?', 4, '[{"text": "Größerer Dynamikbereich", "correct": true, "because": "Mehr Amplitudenstufen"}, {"text": "Höhere Frequenz", "correct": false, "because": "Frequenz durch Abtastrate"}, {"text": "Kleinere Dateien", "correct": false, "because": "Größere Dateien"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Bit-Tiefe von 32 Bit Standard für Audio?', 2, '[{"text": "Nein", "correct": true, "because": "16 oder 24 Bit üblich"}, {"text": "Ja", "correct": false, "because": "32 Bit selten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine höhere Bit-Tiefe?', 5, '[{"text": "Bessere Klangqualität", "correct": true, "because": "Feinere Amplituden"}, {"text": "Größerer Dynamikbereich", "correct": true, "because": "Mehr Lautstärkestufen"}, {"text": "Kleinere Dateien", "correct": false, "because": "Größere Dateien"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Bit-Tiefe unwichtig?', 3, '[{"text": "Dynamikbereich", "correct": false, "because": "Kern der Qualität"}, {"text": "Speicherbedarf", "correct": false, "because": "Beeinflusst Entscheidung"}, {"text": "Aufnahmezeit", "correct": true, "because": "Kein Bit-Tiefenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich die Bit-Tiefe für ein Studio wähle?', 4, '[{"text": "24 Bit für hohe Qualität", "correct": true, "because": "Professioneller Standard"}, {"text": "8 Bit für Schnelligkeit", "correct": false, "because": "Zu niedrige Qualität"}, {"text": "16 Bit für Größe", "correct": false, "because": "Weniger präzise"}]');
